style.css:
@-moz-document domain("docs.google.com") {
/* Main Docs workspace background */
    body,
    .docs-body,
    .kix-appview-editor {
        background-image: url("https://i.pinimg.com/1200x/7d/dc/5c/7ddc5ced8f849e90c4bb4e55cecf55af.jpg") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
    }


    /* Actual page you type on */
    .kix-page {
        background: rgba(255, 255, 255, 0.85) !important;
        backdrop-filter: blur(3px);
        border-radius: 8px !important;
    }


    /* Make the page shadow match */
    .kix-page-content {
        background: transparent !important;
    }


    /* Optional: remove the default grey workspace */
    .docs-material .kix-appview-editor {
        background-color: transparent !important;
    }
}
